insert into public.site_settings (key, value, is_public) values
  ('team', '{"name":"فريق دفء التطوعي","tagline":"دفءٌ منك… وأثرٌ يبقى","about":"مبادرة تطوعية تهدف إلى تعزيز ثقافة العطاء وإعادة الاستفادة من الملابس الصالحة للاستخدام، من خلال تسهيل التبرع بها وتنسيق استلامها، لتصل إلى من يحتاجها.","mission":"نؤمن أن الملابس التي لم نعد بحاجة إليها يمكن أن تكون مصدر دفء وكرامة لغيرنا. نعمل كفريق من المتطوعين على استلام التبرعات وفرزها بعناية، ثم إيصالها إلى مستحقيها بطريقة تحفظ كرامتهم."}'::jsonb, true),
  ('contact', '{"phone":"","whatsapp":"","email":"","address":"","hours":""}'::jsonb, true),
  ('social', '{"instagram":"","x":"","tiktok":"","snapchat":"","facebook":"","youtube":""}'::jsonb, true),
  ('home', '{"hero_title":"دفءٌ منك… وأثرٌ يبقى","hero_subtitle":"ملابس لم تعد بحاجة إليها، قد تكون مصدر دفء وسعادة لغيرك. شاركنا العطاء، ودع أثرك يصل.","about_text":"مبادرة تطوعية تهدف إلى تعزيز ثقافة العطاء وإعادة الاستفادة من الملابس الصالحة للاستخدام، من خلال تسهيل التبرع بها وتنسيق استلامها، لتصل إلى من يحتاجها."}'::jsonb, true),
  ('collection', '{"accepting":true,"notice":""}'::jsonb, true),
  ('privacy', '{"updated_at":"2026-11-01","content":"## مقدمة\nيحرص فريق دفء التطوعي على حماية خصوصيتك. توضح هذه السياسة البيانات التي نجمعها عند تسجيل طلب تبرع، وكيف نستخدمها ونحميها.\n\n## البيانات التي نجمعها\n- الاسم الكامل ورقم الهاتف ورقم واتساب (إن وُجد).\n- المحافظة والولاية ووصف الموقع، والإحداثيات الجغرافية إذا اخترت مشاركتها.\n- معلومات التبرع: فئات الملابس والكمية والحالة والصور الاختيارية والملاحظات.\n- الوقت المفضل للاستلام.\n\n## كيف نستخدم بياناتك\nنستخدم بياناتك فقط للتواصل معك وتنسيق موعد وموقع استلام التبرع، ولإطلاعك على حالة طلبك. لا نبيع بياناتك ولا نشاركها مع أي جهة تجارية، ولا نستخدمها لأغراض تسويقية.\n\n## من يطّلع على بياناتك\nيطّلع على بياناتك أعضاء الفريق المخوّلون فقط، ويرى المتطوع المكلّف بالاستلام البيانات اللازمة لإتمام مهمته فقط.\n\n## الصور\nالصور التي ترفعها اختيارية، وتُحفظ في مساحة تخزين خاصة غير متاحة للعامة، ولا يطّلع عليها إلا أعضاء الفريق المخوّلون.\n\n## الموقع الجغرافي\nمشاركة موقعك الحالي اختيارية تمامًا، ولا نصل إليه إلا بعد موافقتك عبر المتصفح.\n\n## حماية البيانات\nنحفظ البيانات في قاعدة بيانات محمية بصلاحيات وصول مقيدة، ونتّخذ إجراءات تقنية وتنظيمية معقولة لحمايتها من الوصول غير المصرّح به.\n\n## مدة الاحتفاظ بالبيانات\nنحتفظ بالبيانات الشخصية طوال مدة معالجة الطلب، ثم نحذفها أو نجعلها مجهولة الهوية بعد إغلاق الطلب بمدة معقولة، مع الاحتفاظ بإحصاءات عامة لا تكشف هوية أحد.\n\n## حقوقك\nيمكنك طلب الاطلاع على بياناتك أو تصحيحها أو حذفها في أي وقت عبر وسائل التواصل الموضحة في صفحة «تواصل معنا».\n\n## التحديثات\nقد نحدّث هذه السياسة من وقت لآخر، وسيظهر تاريخ آخر تحديث في أعلى الصفحة."}'::jsonb, true)
